import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        StringBuilder output = new StringBuilder();

        int i = 0;
        while (i < input.length()) {
            if (i + 1 < input.length() && input.charAt(i) == 'a' && input.charAt(i + 1) == 't') {
                output.append('@');
                i += 2;
            } else if (i + 2 < input.length() && input.charAt(i) == 'd' && input.charAt(i + 1) == 'o' && input.charAt(i + 2) == 't') {
                output.append('.');
                i += 3;
            } else {
                output.append(input.charAt(i));
                i++;
            }
        }

        String outStr = output.toString();

        boolean firstCharAt = true;
        int length = outStr.length();

        if (length > 0) {
            if (outStr.charAt(0) == '@') {
                System.out.print("at");
            } else if (outStr.charAt(0) == '.') {
                System.out.print("dot");
            } else {
                System.out.print(outStr.charAt(0));
            }
        }

        for (int j = 1; j < length; j++) {
            char ch = outStr.charAt(j);
            if (ch == '@') {
                if (firstCharAt && j != length - 1) {
                    System.out.print("@");
                    firstCharAt = false;
                } else {
                    System.out.print("at");
                }
            } else if (ch == '.') {
                if (j != length - 1) {
                    System.out.print(".");
                } else {
                    System.out.print("dot");
                }
            } else {
                System.out.print(ch);
            }
        }
        System.out.println();
        scanner.close();
    }
}
